from src.filter import drop_empty


def test_drop_empty_basic():
    rows = [["a", "b"], ["", ""], ["c", "d"]]
    assert drop_empty(rows) == [["a", "b"], ["c", "d"]]


def test_drop_empty_no_empty():
    rows = [["a", "b"], ["c", "d"]]
    assert drop_empty(rows) == [["a", "b"], ["c", "d"]]


def test_drop_empty_all_empty():
    rows = [["", ""], ["", ""]]
    assert drop_empty(rows) == []


def test_drop_empty_mixed_empty():
    rows = [["", ""], ["a", ""], ["", "b"], ["", ""]]
    assert drop_empty(rows) == [["a", ""], ["", "b"]]


def test_drop_empty_single_column():
    rows = [["a"], [""], ["c"]]
    assert drop_empty(rows) == [["a"], ["c"]]


def test_drop_empty_preserves_order():
    rows = [["", ""], ["a"], ["", ""], ["b"], ["", ""]]
    assert drop_empty(rows) == [["a"], ["b"]]

